<!DOCTYPE html>
<html lang="vi">
    <head>
        <meta charset="utf-8">
        <meta name="viewport" content="width=device-width, initial-scale=1">
        <meta name="description" content="Toán Lão Sư — prototype giao diện học tập tương tác">
        <title>Toán Lão Sư · UI-001 Prototype</title>
        @vite(['resources/css/app.css', 'resources/js/app.js'])
    </head>
    <body class="min-h-screen bg-slate-50 text-slate-950 antialiased">
        <div class="min-h-screen lg:grid lg:grid-cols-[17rem_1fr]">
            <aside class="hidden border-r border-slate-200 bg-white lg:flex lg:flex-col">
                <div class="flex h-20 items-center gap-3 border-b border-slate-100 px-6">
                    <span class="flex size-10 items-center justify-center rounded-2xl bg-indigo-600 text-lg font-bold text-white">TL</span>
                    <div>
                        <p class="font-semibold tracking-tight">Toán Lão Sư</p>
                        <p class="text-xs text-slate-500">Học bằng cách khám phá</p>
                    </div>
                </div>
                <nav aria-label="Điều hướng workspace" class="flex-1 space-y-1 p-4 text-sm">
                    <a href="#student" class="flex items-center gap-3 rounded-xl bg-indigo-50 px-3 py-2.5 font-semibold text-indigo-700"><span aria-hidden="true">⌂</span> Tổng quan</a>
                    <a href="#learning" class="flex items-center gap-3 rounded-xl px-3 py-2.5 text-slate-600 hover:bg-slate-50"><span aria-hidden="true">◎</span> Tiếp tục học</a>
                    <a href="#scene" class="flex items-center gap-3 rounded-xl px-3 py-2.5 text-slate-600 hover:bg-slate-50"><span aria-hidden="true">◇</span> Mô hình 2D</a>
                    <a href="#exam" class="flex items-center gap-3 rounded-xl px-3 py-2.5 text-slate-600 hover:bg-slate-50"><span aria-hidden="true">□</span> Kỳ thi</a>
                    <a href="#chat" class="flex items-center gap-3 rounded-xl px-3 py-2.5 text-slate-600 hover:bg-slate-50"><span aria-hidden="true">✦</span> Gia sư AI</a>
                </nav>
                <div class="border-t border-slate-100 p-4">
                    <div class="flex items-center gap-3 rounded-2xl bg-slate-50 p-3">
                        <span class="flex size-9 items-center justify-center rounded-full bg-amber-100 text-sm font-bold text-amber-700">A</span>
                        <div class="min-w-0 flex-1"><p class="truncate text-sm font-semibold">An Nguyễn</p><p class="text-xs text-slate-500">Học sinh</p></div>
                        <button type="button" aria-label="Mở menu tài khoản" class="rounded-lg p-2 text-slate-500 hover:bg-white">•••</button>
                    </div>
                </div>
            </aside>

            <main class="min-w-0">
                <header class="sticky top-0 z-10 flex h-16 items-center justify-between border-b border-slate-200/80 bg-white/90 px-4 backdrop-blur sm:px-6 lg:px-10">
                    <div class="flex items-center gap-3 lg:hidden"><span class="flex size-9 items-center justify-center rounded-xl bg-indigo-600 text-sm font-bold text-white">TL</span><span class="font-semibold">Toán Lão Sư</span></div>
                    <div class="hidden items-center gap-2 text-sm text-slate-500 sm:flex"><span>Workspace</span><span aria-hidden="true">/</span><span class="font-medium text-slate-900">Student prototype</span></div>
                    <div class="flex items-center gap-2"><button type="button" class="hidden rounded-xl border border-slate-200 px-3 py-2 text-sm text-slate-600 sm:inline-flex">Trợ giúp</button><button type="button" class="flex size-10 items-center justify-center rounded-xl border border-slate-200 text-slate-700" aria-label="Thông báo">♧</button></div>
                </header>

                <div class="mx-auto max-w-7xl space-y-8 px-4 py-6 sm:px-6 lg:px-10 lg:py-10">
                    <section id="student" class="grid gap-6 xl:grid-cols-[1fr_20rem]">
                        <div class="rounded-3xl bg-slate-950 p-6 text-white shadow-xl shadow-indigo-100 sm:p-8">
                            <div class="flex flex-wrap items-start justify-between gap-4"><div><p class="mb-3 text-sm font-medium text-indigo-200">Thứ Hai, 23 tháng 11</p><h1 class="max-w-xl text-3xl font-semibold tracking-tight sm:text-4xl">Mỗi lần thử là một bước hiểu sâu hơn.</h1><p class="mt-4 max-w-lg text-sm leading-6 text-slate-300">Tiếp tục bài học đang dở và dùng mô hình động để nhìn thấy quy luật thay đổi.</p></div><span class="rounded-full border border-white/15 bg-white/10 px-3 py-1.5 text-xs text-indigo-100">Prototype UI-001</span></div>
                            <div class="mt-8 flex flex-wrap gap-3"><a href="#learning" class="inline-flex min-h-11 items-center justify-center rounded-xl bg-indigo-500 px-4 py-2.5 text-sm font-semibold text-white hover:bg-indigo-400">Tiếp tục học <span class="ml-2" aria-hidden="true">→</span></a><a href="#scene" class="inline-flex min-h-11 items-center justify-center rounded-xl border border-white/20 px-4 py-2.5 text-sm font-semibold text-white hover:bg-white/10">Mở mô hình 2D</a></div>
                        </div>
                        <div class="rounded-3xl border border-slate-200 bg-white p-6"><div class="flex items-center justify-between"><h2 class="font-semibold">Hôm nay</h2><span class="text-xs text-emerald-600">Đang tiến bộ</span></div><div class="mt-6 grid grid-cols-2 gap-3"><div class="rounded-2xl bg-indigo-50 p-4"><p class="text-2xl font-semibold text-indigo-700">42</p><p class="mt-1 text-xs text-slate-600">phút học</p></div><div class="rounded-2xl bg-amber-50 p-4"><p class="text-2xl font-semibold text-amber-700">3</p><p class="mt-1 text-xs text-slate-600">câu cần ôn</p></div></div><div class="mt-5 flex items-center justify-between text-sm"><span class="text-slate-500">Chuỗi ngày học</span><span class="font-semibold">5 ngày 🔥</span></div></div>
                    </section>

                    <section id="learning" class="space-y-4"><div class="flex items-end justify-between gap-4"><div><p class="text-sm font-medium text-indigo-600">Tiếp tục học</p><h2 class="mt-1 text-2xl font-semibold tracking-tight">Hàm số và chuyển động</h2></div><a href="#" class="hidden text-sm font-semibold text-indigo-600 sm:block">Xem tất cả →</a></div><div class="grid gap-4 md:grid-cols-3"><article class="rounded-3xl border border-indigo-100 bg-white p-5 shadow-sm md:col-span-2"><div class="flex flex-wrap items-start justify-between gap-4"><div><span class="rounded-full bg-indigo-50 px-2.5 py-1 text-xs font-semibold text-indigo-700">Bài 04 · Block 3/6</span><h3 class="mt-4 text-xl font-semibold">Máy bay đi vào vùng radar</h3><p class="mt-2 text-sm leading-6 text-slate-600">Dùng khoảng cách từ điểm đến tâm để dự đoán thời điểm phát hiện.</p></div><span class="text-sm font-semibold text-slate-500">58%</span></div><div class="mt-6 h-2 rounded-full bg-slate-100"><div class="h-2 w-[58%] rounded-full bg-indigo-600"></div></div><div class="mt-5 flex flex-wrap items-center justify-between gap-3 text-sm"><span class="text-slate-500">Còn khoảng 12 phút</span><a href="#scene" class="font-semibold text-indigo-600">Mở bài học →</a></div></article><article class="rounded-3xl border border-slate-200 bg-white p-5"><span class="rounded-full bg-emerald-50 px-2.5 py-1 text-xs font-semibold text-emerald-700">Đã mở khóa</span><h3 class="mt-4 font-semibold">Hình khai triển chiếc hộp</h3><p class="mt-2 text-sm leading-6 text-slate-600">Tìm đường ngắn nhất của con kiến qua các mặt hộp.</p><div class="mt-6 flex items-center justify-between text-sm"><span class="text-slate-500">2/5 block</span><button type="button" class="font-semibold text-indigo-600">Xem trước</button></div></article></div></section>

                    <section id="scene" class="grid gap-6 xl:grid-cols-[1fr_22rem]"><div class="overflow-hidden rounded-3xl border border-slate-200 bg-white"><div class="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 px-5 py-4"><div><p class="text-xs font-semibold uppercase tracking-[0.18em] text-indigo-600">Scene 2D · đang chạy</p><h2 class="mt-1 text-lg font-semibold">Radar và đường bay</h2></div><span class="rounded-full bg-rose-50 px-3 py-1 text-xs font-semibold text-rose-700">Đã phát hiện</span></div><div class="relative aspect-[16/9] min-h-64 bg-slate-950 p-4 sm:p-8"><div class="absolute inset-0 opacity-30" style="background-image: linear-gradient(#64748b 1px, transparent 1px), linear-gradient(90deg, #64748b 1px, transparent 1px); background-size: 32px 32px;"></div><div class="absolute left-1/2 top-1/2 size-40 -translate-x-1/2 -translate-y-1/2 rounded-full border border-indigo-300/60 bg-indigo-500/15 sm:size-56"></div><div class="absolute left-[16%] top-[68%] h-px w-[70%] origin-left rotate-[-24deg] bg-slate-400"></div><div class="absolute left-[62%] top-[35%] size-4 rounded-full bg-rose-400 shadow-[0_0_0_6px_rgba(251,113,133,0.2)]" title="Máy bay"></div><div class="absolute left-[48%] top-[48%] flex size-8 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full bg-indigo-500 text-xs text-white">R</div><div class="absolute bottom-4 left-4 rounded-xl bg-slate-900/80 px-3 py-2 text-xs text-slate-200">d(t) = 4.2 km · t = 08:14</div></div><div class="flex flex-wrap items-center gap-2 border-t border-slate-100 p-4"><button type="button" class="min-h-11 rounded-xl bg-indigo-600 px-4 text-sm font-semibold text-white">Ⅱ Tạm dừng</button><button type="button" class="min-h-11 rounded-xl border border-slate-200 px-4 text-sm font-semibold text-slate-700">↺ Đặt lại</button><label class="flex min-h-11 flex-1 items-center gap-3 px-2 text-sm text-slate-500"><span class="sr-only">Thời điểm mô phỏng</span><input type="range" min="0" max="100" value="64" class="w-full accent-indigo-600"><span>64%</span></label></div></div><aside id="chat" class="rounded-3xl border border-slate-200 bg-white p-5"><div class="flex items-start justify-between gap-3"><div><p class="text-xs font-semibold uppercase tracking-[0.18em] text-indigo-600">Gia sư AI</p><h2 class="mt-1 text-lg font-semibold">Muốn khám phá tiếp?</h2></div><span class="size-2.5 rounded-full bg-emerald-500" title="Đang sẵn sàng"></span></div><div class="mt-5 rounded-2xl bg-slate-50 p-4 text-sm leading-6 text-slate-700">Nếu tăng vận tốc, máy bay sẽ vào vùng kiểm soát sớm hơn hay muộn hơn? Hãy thử kéo thanh thời gian và quan sát <span class="font-semibold">d(t)</span>.</div><div class="mt-4 flex flex-wrap gap-2"><button type="button" class="rounded-full border border-slate-200 px-3 py-2 text-xs font-medium text-slate-600">Gợi ý một bước</button><button type="button" class="rounded-full border border-slate-200 px-3 py-2 text-xs font-medium text-slate-600">Giải thích công thức</button></div><div class="mt-5 flex items-center gap-2 border-t border-slate-100 pt-4"><button type="button" class="min-h-11 flex-1 rounded-xl bg-slate-950 px-3 text-sm font-semibold text-white">Hỏi gia sư</button><span class="text-xs text-slate-400">Nguồn: Bài 04</span></div></aside></section>

                    <section id="exam" class="rounded-3xl border border-slate-200 bg-white p-5 sm:p-6"><div class="flex flex-wrap items-center justify-between gap-4"><div><p class="text-sm font-medium text-indigo-600">Thi online</p><h2 class="mt-1 text-xl font-semibold">TSA · Toán định lượng</h2><p class="mt-2 text-sm text-slate-500">Ca thi sắp tới · Đồng hồ lấy theo máy chủ</p></div><div class="rounded-2xl bg-amber-50 px-4 py-3 text-center"><p class="text-xs text-amber-700">Bắt đầu sau</p><p class="mt-1 text-xl font-semibold text-amber-900">02:14:08</p></div></div><div class="mt-5 grid gap-3 text-sm sm:grid-cols-3"><div class="rounded-2xl bg-slate-50 p-4"><p class="text-slate-500">Thời lượng</p><p class="mt-1 font-semibold">90 phút</p></div><div class="rounded-2xl bg-slate-50 p-4"><p class="text-slate-500">Câu hỏi</p><p class="mt-1 font-semibold">40 câu</p></div><div class="rounded-2xl bg-slate-50 p-4"><p class="text-slate-500">Trạng thái</p><p class="mt-1 font-semibold text-emerald-700">Đã kiểm tra kết nối</p></div></div></section>
                </div>

                <nav aria-label="Điều hướng mobile" class="sticky bottom-0 z-20 grid grid-cols-5 border-t border-slate-200 bg-white/95 px-2 py-2 backdrop-blur lg:hidden"><a href="#student" class="flex flex-col items-center gap-1 rounded-xl px-2 py-2 text-[11px] font-semibold text-indigo-600"><span aria-hidden="true">⌂</span>Home</a><a href="#learning" class="flex flex-col items-center gap-1 rounded-xl px-2 py-2 text-[11px] text-slate-500"><span aria-hidden="true">◎</span>Học</a><a href="#scene" class="flex flex-col items-center gap-1 rounded-xl px-2 py-2 text-[11px] text-slate-500"><span aria-hidden="true">◇</span>Scene</a><a href="#exam" class="flex flex-col items-center gap-1 rounded-xl px-2 py-2 text-[11px] text-slate-500"><span aria-hidden="true">□</span>Thi</a><a href="#chat" class="flex flex-col items-center gap-1 rounded-xl px-2 py-2 text-[11px] text-slate-500"><span aria-hidden="true">✦</span>AI</a></nav>
                <section data-scene-runtime data-scene-type="radar" aria-labelledby="scene-runtime-title" class="mt-8 rounded-3xl border border-indigo-100 bg-white p-5 shadow-sm sm:p-6">
                    <div class="flex flex-wrap items-start justify-between gap-4"><div><p class="text-xs font-semibold uppercase tracking-[0.18em] text-indigo-600">UI-007 · Scene runtime</p><h2 id="scene-runtime-title" data-scene-title class="mt-2 text-xl font-semibold">Radar và đường bay</h2><p data-scene-description class="mt-2 text-sm text-slate-600">Máy bay tiến vào vùng kiểm soát của radar.</p></div><span data-scene-status class="rounded-full bg-emerald-50 px-3 py-1 text-xs font-semibold text-emerald-700">Tạm dừng</span></div>
                    <div data-scene-stage class="mt-5 aspect-[16/9] overflow-hidden rounded-2xl bg-slate-950" aria-live="polite"></div>
                    <div class="mt-4 flex flex-wrap gap-2" role="group" aria-label="Chọn mô hình 2D"><button data-scene-type="radar" type="button" class="rounded-full bg-indigo-50 px-3 py-2 text-xs font-semibold text-indigo-700">Radar</button><button data-scene-type="ant" type="button" class="rounded-full border border-slate-200 px-3 py-2 text-xs font-semibold text-slate-700">Kiến · hộp</button><button data-scene-type="graph" type="button" class="rounded-full border border-slate-200 px-3 py-2 text-xs font-semibold text-slate-700">Đồ thị</button><button data-scene-type="surface" type="button" class="rounded-full border border-slate-200 px-3 py-2 text-xs font-semibold text-slate-700">Mặt cong</button></div>
                    <div class="mt-4 flex flex-wrap items-center gap-3"><button data-scene-play type="button" class="min-h-11 rounded-xl bg-indigo-600 px-4 text-sm font-semibold text-white">▶ Chạy / tạm dừng</button><button data-scene-reset type="button" class="min-h-11 rounded-xl border border-slate-200 px-4 text-sm font-semibold text-slate-700">↺ Đặt lại</button><label class="flex min-h-11 min-w-48 flex-1 items-center gap-3 text-xs text-slate-500"><span class="sr-only">Tiến trình mô phỏng</span><input data-scene-progress type="range" min="0" max="100" value="0" class="w-full accent-indigo-600"><span data-scene-progress-label>0%</span></label></div>
                </section>
            </main>
        </div>
    </body>
</html>
